// ta — தமிழ்.
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// TOM: **நீங்கள்**, e é a sexta língua seguida com o mesmo raciocínio — já é o padrão, não a exceção.
// O tâmil tem **நீ**, que é de intimidade (irmão, amigo de infância, criança) e, com quem acabou de
// chegar, soa atrevido. நீங்கள் é o neutro entre adultos e não carrega a distância do "senhor".
//
// ===================================================================================================
// O MEU PRÓPRIO BILHETE SOBRE ESTA LÍNGUA ESTAVA ERRADO, e a medição o desmentiu.
//
// A tabela de armadilhas em scripts/fila-de-idiomas.mjs dizia "tâmil: algarismos próprios". O tâmil
// TEM algarismos próprios (௦௧௨௩), mas eles são arcaicos, e o que o navegador desenha é outro:
//
//   Intl.NumberFormat('ta').resolvedOptions().numberingSystem  →  latn
//   Intl.NumberFormat('ta').format(1234567)                    →  12,34,567
//
// Latinos, com o agrupamento indiano (de dois em dois depois do primeiro grupo de três, como no
// télugo). Os números deste dicionário são 0-9 por causa disso, e não por descuido.
//
// A LIÇÃO NÃO É "ERREI": é que um fato que o computador sabe medir não deve ser copiado para um
// bilhete escrito à mão, porque o bilhete não é conferido por ninguém. As notas da fila pararam de
// falar de algarismo; quem fala agora é a medição que o `--proximo` imprime antes de cada tradução.
// ===================================================================================================
//
// A ARMADILHA DE VERDADE DESTA LÍNGUA É O COMPRIMENTO. O tâmil é aglutinante: "திரைப் பகிர்வைப்
// பார்ப்பதை நிறுத்து" é um botão só. Foi medido nas onze abas e nada estourou — mas é a língua em
// que isso esteve mais perto, e vale conferir de novo em qualquer tela estreita que apareça depois.
//
// VOCABULÁRIO, decidido uma vez: comunidade = சமூகம், canal = சேனல், sala/canal de voz = குரல் சேனல்,
// அறை quando é a sala onde se está, mensagem = செய்தி, senha = கடவுச்சொல், lixeira = குப்பைத் தொட்டி,
// tópico = இழை, insígnia = பேட்ஜ், selo (os quatro caracteres da comunidade) = குறிச்சொல்,
// avatar = சுயவிவரப் படம், transmissão de tela = திரைப் பகிர்வு.
//
// Gerado por: node scripts/idiomas.mjs --novo ta

