  'Excluir minha conta para sempre': 'என் கணக்கை நிரந்தரமாக நீக்கு',
  'Excluir sala de voz': 'குரல் சேனலை நீக்கு',
  'Explorar': 'ஆராய்',
  'Fale algo: a barra deve se mexer com a sua voz.': 'ஏதாவது பேசுங்கள்: உங்கள் குரலுக்கேற்ப பட்டை அசைய வேண்டும்.',
  'Falta só confirmar': 'உறுதிப்படுத்துவது மட்டுமே மீதம்',
  'faz a letra acender sozinha no tempo certo; um': 'வரிகளைச் சரியான நேரத்தில் தானே ஒளிரச் செய்யும்; ஆனால்',
