  'Fechar tópico': 'இழையை மூடு',
  'Fica assim:': 'இப்படி ஆகும்:',
  'Floresta': 'காடு',
  'Fluido': 'மென்மையாக',
  'Folha': 'இலை',
  'Funcionam mesmo com o Syden minimizado, durante uma chamada:': 'அழைப்பின்போது, Syden சிறிதாக்கப்பட்டிருந்தாலும் இவை வேலை செய்யும்:',
  'Fundo do perfil': 'சுயவிவரப் பின்னணி',
  'Ganha fazendo alguma coisa no Syden': 'Sydenஇல் ஏதாவது செய்தால் கிடைக்கும்',
  'Gerar outro': 'இன்னொன்றை உருவாக்கு',
  'GIF': 'GIF',
  'GIFs': 'GIF',
  'GIFs pelo GIPHY': 'GIFகள் GIPHY வழங்குகிறது',
  'Grava a sua voz e toca de volta com o efeito, só para você.': 'உங்கள் குரலைப் பதிவுசெய்து, விளைவுடன் திரும்ப ஒலிக்கும் — உங்களுக்கு மட்டும்.',
  'Gravando… daqui a pouco dá para clipar': 'பதிவாகிறது… சற்று கழித்து கிளிப் செய்யலாம்',
  'Gravando… fale algo': 'பதிவாகிறது… ஏதாவது பேசுங்கள்',
  'Gravar 3 segundos e ouvir': '3 வினாடிகள் பதிவுசெய்து கேளுங்கள்',
  'Gravar um recado em vídeo': 'ஒரு காணொளிச் செய்தியைப் பதிவுசெய்',
  'Guardar': 'சேமி',
  'Helicóptero': 'உலங்கூர்தி',
  'Hoje dá para atender {paises} países da ONU; a lista abaixo cobre praticamente todos os outros.': 'இன்று ஐக்கிய நாடுகளின் {paises} நாடுகளை எட்ட முடியும்; கீழுள்ள பட்டியல் மீதமுள்ள கிட்டத்தட்ட அனைத்தையும் உள்ளடக்கும்.',
  'Ícone': 'சின்னம்',
  'Idioma': 'மொழி',
  'Imagem': 'படம்',
  'Informações da transmissão': 'திரைப் பகிர்வுத் தகவல்',
  'Início': 'முகப்பு',
  'Início do Syden': 'Syden முகப்பு',
  'Insígnias': 'பேட்ஜ்கள்',
  'Instalar': 'நிறுவு',
  'Instalar o Syden': 'Sydenஐ நிறுவு',
  'Ir para os canais': 'சேனல்களுக்குச் செல்',
  'Isso está demorando mais do que o normal.': 'இது வழக்கத்தைவிட அதிக நேரம் எடுக்கிறது.',
  'Já está no seu perfil. Em Configurações você escolhe quais insígnias exibir.': 'இது உங்கள் சுயவிவரத்தில் சேர்ந்துவிட்டது. எந்தப் பேட்ஜ்களைக் காட்டுவது என்பதை அமைப்புகளில் தேர்ந்தெடுக்கிறீர்கள்.',
  'Já pode entrar com a senha nova. Os aparelhos que estavam conectados foram desconectados, por segurança.': 'இப்போது புதிய கடவுச்சொல்லுடன் உள்நுழையலாம். பாதுகாப்புக்காக உள்நுழைந்திருந்த சாதனங்கள் வெளியேற்றப்பட்டன.',
  'Já recebeu um código de alguém? É por aqui.': 'யாராவது குறியீடு கொடுத்தார்களா? இந்தப் பக்கம்.',
  'Já tem uma conta? ': 'ஏற்கெனவே கணக்கு உள்ளதா? ',
  'Jade': 'பச்சைக்கல்',
  'Jogo': 'விளையாட்டு',
  'Karaokê': 'கரோக்கே',
  'Laranja': 'ஆரஞ்சு',
  'Laranja que pulsa.': 'துடிக்கும் ஆரஞ்சு.',
