  'Prefere usar como programa?': 'செயலியாகப் பயன்படுத்த விரும்புகிறீர்களா?',
  'Prisma': 'பட்டகம்',
  'Privacidade': 'தனியுரிமை',
  'Processamento de voz': 'குரல் செயலாக்கம்',
  'Procurando…': 'தேடுகிறது…',
  'Procurar GIF': 'GIF தேடு',
  'Progresso de {marco}': '{marco} முன்னேற்றம்',
  'Pronto: só este aparelho continua conectado.': 'முடிந்தது: இப்போது இந்தச் சாதனம் மட்டுமே உள்நுழைந்திருக்கிறது.',
  'Pronto. Quem entrar agora vai ver isto.': 'முடிந்தது. இனி வருபவர்களுக்கு இது தெரியும்.',
  'Qualidade do compartilhamento de tela': 'திரைப் பகிர்வின் தரம்',
  'Quatro caracteres, um ícone e uma cor que aparecem ao lado do nome de quem é daqui.': 'நான்கு எழுத்துகள், ஒரு சின்னம், ஒரு நிறம் — இங்குள்ளவர்களின் பெயருக்கு அருகில் தெரியும்.',
  'Que bom te ver de novo.': 'உங்களை மீண்டும் பார்ப்பது மகிழ்ச்சி.',
  'Que legal!': 'அருமை!',
  'Jogando agora': "இப்போது விளையாடுகிறார்கள்",
  'Estou aqui': "நான் இங்கே இருக்கிறேன்",
  'Ao abrir o Syden': "Syden திறக்கும்போது",
  'No quarto': "அறையில்",
  'Onde parei': "கடைசி இடத்தில்",
  'Aniversário do Syden': "Syden-இன் பிறந்தநாள்",
  'Hoje é aniversário do Syden!': "இன்று Syden-இன் பிறந்தநாள்!",
  'O Syden nasceu em {data}. Valeu por fazer parte desta história.': "Syden {data} அன்று பிறந்தது. இந்தக் கதையின் ஒரு பகுதியாக இருப்பதற்கு நன்றி.",
  'Quem mais cantou': "அதிகம் பாடியவர்",
  'Mais cantadas': "அதிகம் பாடப்பட்டவை",
  'Músicas cantadas: {n}': "பாடப்பட்ட பாடல்கள்: {n}",
  'Ninguém cantou ainda. Conta quando alguém põe uma música com a turma na sala.': "இன்னும் யாரும் பாடவில்லை. குழு அறையில் இருக்கும்போது யாராவது பாடலைப் போட்டால் கணக்கில் வரும்.",
  'Idiomas': "மொழிகள்",
  'Idiomas falados': "பேசும் மொழிகள்",
  'Idiomas em estudo': "கற்கும் மொழிகள்",
  'Aparece no seu cartão de perfil, para quem fala um idioma achar quem o estuda. É opcional.': "உன் சுயவிவர அட்டையில் தெரியும்; ஒரு மொழி பேசுபவர் அதைக் கற்பவரைக் கண்டுபிடிக்க. விருப்பத்தேர்வு.",
  'Feliz aniversário, {nome}!': 'பிறந்தநாள் வாழ்த்துகள், {nome}!',
  'Que este ano venha cheio de boas conversas, boas partidas e boa companhia.': 'இந்த ஆண்டு நல்ல உரையாடல்கள், நல்ல விளையாட்டுகள், நல்ல நட்பால் நிறையட்டும்.',
  'Quem abre o site': 'தளத்தைத் திறப்பவர்கள்',
  'Quem anda com você': 'உங்களுடன் இருப்பவர்கள்',
  'Quem canta': 'பாடுபவர்',
  'quem cuida do Syden': 'Sydenஐக் கவனிப்பவர்',
  'Quem cuida do Syden vai olhar. Obrigado por avisar.': 'Sydenஐக் கவனிப்பவர் பார்ப்பார். தெரிவித்ததற்கு நன்றி.',
  'Quem está aqui não vê as suas mensagens nem você as dele, não consegue abrir conversa privada com você e não pode te mandar pedido de amizade.': 'இங்கே இருப்பவருக்கு உங்கள் செய்திகள் தெரியாது, உங்களுக்கு அவருடையதும் தெரியாது; அவர் உங்களுடன் தனி உரையாடலைத் தொடங்க முடியாது, நட்புக் கோரிக்கையும் அனுப்ப முடியாது.',
  'Quem estiver na sala será desconectado. Dá para trazer a sala de volta por {dias} dias, em Configurações → Comunidade → Lixeira.': 'அறையில் இருப்பவர்கள் அனைவரும் வெளியேற்றப்படுவார்கள். {dias} நாட்கள் வரை அமைப்புகள் → சமூகம் → குப்பைத் தொட்டியிலிருந்து அறையைத் திரும்பக் கொண்டுவரலாம்.',
  'Quem falou': 'யார் பேசினார்',
  'Quem tiver este código entra na comunidade: pela tela de cadastro, se ainda não tem conta, ou pelo botão de entrar, se já usa o Syden.': 'இந்தக் குறியீடு உள்ளவர் சமூகத்தில் சேரலாம்: கணக்கு இல்லையென்றால் பதிவுத் திரையிலிருந்து, ஏற்கெனவே Syden பயன்படுத்துபவரானால் உள்நுழைவுப் பொத்தானிலிருந்து.',
  'Quente, mas sem gritar.': 'சூடானது, ஆனால் கூச்சலிடாதது.',
  'Querem falar': 'பேச விரும்புகிறார்கள்',
  'Rádio de avião': 'விமான வானொலி',
  'Recado': 'செய்தி',
  'Quem dá o recado': 'செய்தியை யார் தருகிறார்',
  'Recomendado para a maioria. Quem assiste pode baixar a qualidade se precisar.': 'பெரும்பாலானோருக்குப் பொருத்தம். தேவைப்பட்டால் பார்ப்பவர் தரத்தைக் குறைத்துக்கொள்ளலாம்.',
  'Reconectando ao servidor…': 'சேவையகத்துடன் மீண்டும் இணைகிறது…',
  'Reduz barulhos de fundo, como teclado, ventilador e trânsito.': 'விசைப்பலகை, மின்விசிறி, வாகனங்கள் போன்ற பின்னணிச் சத்தங்களைக் குறைக்கும்.',
  'Registro': 'பதிவு',
