  'Rubi': 'மாணிக்கம்',
  'Sair': 'வெளியேறு',
  'Sair da comunidade': 'சமூகத்தை விட்டு வெளியேறு',
  'Sair da conta': 'கணக்கிலிருந்து வெளியேறு',
  'Sair da tela cheia': 'முழுத்திரையிலிருந்து வெளியேறு',
  'Sair de {comunidade}? As suas mensagens continuam lá para quem ficou.': '{comunidade}ஐ விட்டு வெளியேறவா? மீதமுள்ளவர்களுக்காக உங்கள் செய்திகள் அங்கேயே இருக்கும்.',
