  'Apagar tudo': 'அனைத்தையும் அழி',
  '{texto} — quase!': '{texto} — நெருங்கிவிட்டாய்!',
  'acertou!': 'சரியாகக் கண்டுபிடித்தார்!',
  'Você acertou!': 'சரியாகக் கண்டுபிடித்தாய்!',
  'Seu chute…': 'உன் பதில்…',
  'Desenha e adivinha': 'வரைந்து கண்டுபிடி',
  'Cada um desenha uma vez, e a sala chuta o que é. Quem acerta mais rápido ganha mais pontos.': 'ஒவ்வொருவரும் ஒரு முறை வரைவார்கள், அறையில் உள்ளவர்கள் அது என்ன என்று கண்டுபிடிப்பார்கள். வேகமாகக் கண்டுபிடிப்பவருக்கு அதிகப் புள்ளிகள்.',
