  '{tamanho} · de {quem}': '{tamanho} · {quem}-இடமிருந்து',
  'grande demais para o chat, mas dá para guardar no computador': 'அரட்டைக்கு மிகப் பெரியது, ஆனால் கணினியில் சேமிக்கலாம்',
  'Mandar em': 'அனுப்பும் இடம்',
  'Guardar no computador': 'கணினியில் சேமி',
  'Mandado!': 'அனுப்பப்பட்டது!',
  'Mandando…': 'அனுப்புகிறது…',
  'Mandar na conversa': 'உரையாடலில் அனுப்பு',
  'Obrigado de verdade. Fique de olho nas novidades da tela inicial para ver a sua ideia funcionando — e a medalha de contribuição já está no seu perfil.': 'உண்மையிலேயே நன்றி. உங்கள் யோசனை செயல்படுவதைப் பார்க்க முகப்புத் திரையின் புதியவற்றைக் கவனியுங்கள் — பங்களிப்புப் பதக்கம் ஏற்கெனவே உங்கள் சுயவிவரத்தில் உள்ளது.',
  'Criar comunidade': 'சமூகத்தை உருவாக்கு',
  'Criar': 'உருவாக்கு',
  'Calendário': 'நாள்காட்டி',
  'Mês anterior': 'முந்தைய மாதம்',
  'Próximo mês': 'அடுத்த மாதம்',
  'Nada marcado neste mês.': 'இந்த மாதம் எதுவும் இல்லை.',
  'Apagar evento': 'நிகழ்வை நீக்கு',
  'Aniversário de {nome}': '{nome} பிறந்தநாள்',
  'Novo evento': 'புதிய நிகழ்வு',
  'Nome do evento': 'நிகழ்வின் பெயர்',
  'Data': 'தேதி',
  'Hora': 'நேரம்',
  'Abra ele e a sua conta está pronta — é o que garante que você consiga recuperar a senha um dia, se esquecer.': 'அதைத் திறந்தால் உங்கள் கணக்கு தயார் — எப்போதாவது கடவுச்சொல் மறந்தால் அதை மீட்க உதவுவது இதுதான்.',
  'Não chegou em alguns minutos? Dê uma olhada no spam ou nas promoções. Se não estiver lá, mande de novo.': 'சில நிமிடங்களில் வரவில்லையா? ஸ்பேம் அல்லது விளம்பரங்களில் பாருங்கள். அங்கும் இல்லையென்றால் மீண்டும் அனுப்புங்கள்.',
  'Mandar o link de novo': 'இணைப்பை மீண்டும் அனுப்பு',
  'Enviar denúncia': 'புகாரை அனுப்பு',
  'Nenhuma conversa ainda. Clique com o botão direito em alguém da comunidade e escolha "Enviar mensagem".': 'இன்னும் உரையாடல்கள் இல்லை. சமூகத்தில் யாரையாவது வலது-கிளிக் செய்து "செய்தியை அனுப்பு" என்பதைத் தேர்ந்தெடுங்கள்.',
  '{n} pessoas': '{n} பேர்',
  'Sem mensagens ainda': 'இன்னும் செய்திகள் இல்லை',
  'Conversas (1 com mensagem nova)': 'உரையாடல்கள் (1-இல் புதிய செய்தி)',
  'Conversas ({n} com mensagem nova)': 'உரையாடல்கள் ({n}-இல் புதிய செய்தி)',
  'Conversas, 1 com mensagem nova': 'உரையாடல்கள், 1-இல் புதிய செய்தி',
  'Conversas, {n} com mensagem nova': 'உரையாடல்கள், {n}-இல் புதிய செய்தி',
  'Mandar um efeito para a sala': 'அறைக்கு ஒரு விளைவை அனுப்பு',
