  'sem notas ainda': 'இன்னும் மதிப்பீடுகள் இல்லை',
  '1 emoji saiu de {comunidade}.': '{comunidade}-இலிருந்து 1 ஈமோஜி நீங்கியது.',
  '{n} emojis saíram de {comunidade}.': '{comunidade}-இலிருந்து {n} ஈமோஜிகள் நீங்கின.',
  '1 emoji entrou. Ficaram de fora, porque a comunidade já tem esses nomes: {nomes}': '1 ஈமோஜி சேர்ந்தது. சமூகத்தில் இந்தப் பெயர்கள் ஏற்கெனவே இருப்பதால் இவை சேரவில்லை: {nomes}',
  '{n} emojis entraram. Ficaram de fora, porque a comunidade já tem esses nomes: {nomes}': '{n} ஈமோஜிகள் சேர்ந்தன. சமூகத்தில் இந்தப் பெயர்கள் ஏற்கெனவே இருப்பதால் இவை சேரவில்லை: {nomes}',
  'Pronto: 1 emoji entrou em {comunidade}.': 'முடிந்தது: {comunidade}-இல் 1 ஈமோஜி சேர்ந்தது.',
  'Pronto: {n} emojis entraram em {comunidade}.': 'முடிந்தது: {comunidade}-இல் {n} ஈமோஜிகள் சேர்ந்தன.',
  'Emoji acrescentado — quem já tem o pacote recebeu na hora.': 'ஈமோஜி சேர்க்கப்பட்டது — தொகுப்பு வைத்திருப்பவர்களுக்கு உடனே கிடைத்தது.',
  '{n} emojis acrescentados — quem já tem o pacote recebeu na hora.': '{n} ஈமோஜிகள் சேர்க்கப்பட்டன — தொகுப்பு வைத்திருப்பவர்களுக்கு உடனே கிடைத்தன.',
  'Emoji acrescentado ao pacote.': 'தொகுப்பில் ஈமோஜி சேர்க்கப்பட்டது.',
  '{n} emojis acrescentados ao pacote.': 'தொகுப்பில் {n} ஈமோஜிகள் சேர்க்கப்பட்டன.',
  ':{nome}: saiu do pacote e das comunidades que o usam.': ':{nome}: தொகுப்பிலிருந்தும் அதைப் பயன்படுத்தும் சமூகங்களிலிருந்தும் நீங்கியது.',
  ':{nome}: saiu do pacote.': ':{nome}: தொகுப்பிலிருந்து நீங்கியது.',
  'em {comunidade}': '{comunidade}-இல்',
  'Sem descrição.': 'விளக்கம் இல்லை.',
  'Feito por {pessoa}': 'உருவாக்கியவர் {pessoa}',
  'alguém que saiu': 'வெளியேறிய ஒருவர்',
  '1 emoji': '1 ஈமோஜி',
  '{n} emojis': '{n} ஈமோஜிகள்',
  '1 comunidade usa': '1 சமூகம் பயன்படுத்துகிறது',
  '{n} comunidades usam': '{n} சமூகங்கள் பயன்படுத்துகின்றன',
  'Tirar :{nome}: do pacote': ':{nome}:-ஐத் தொகுப்பிலிருந்து நீக்கு',
  'Só quem administra a comunidade pode mexer nos emojis dela': 'சமூகத்தின் ஈமோஜிகளை அதன் நிர்வாகிகள் மட்டுமே மாற்ற முடியும்',
  'Esconder os emojis': 'ஈமோஜிகளை மறை',
