  'PNG, JPG, GIF ou WEBP; cada um vira um quadradinho de 128 pixels. No máximo {n} emojis por pacote.': 'PNG, JPG, GIF அல்லது WEBP; ஒவ்வொன்றும் 128 பிக்சல் சிறு சதுரமாகும். ஒரு தொகுப்பில் அதிகபட்சம் {n} ஈமோஜிகள்.',
  'Nome do emoji {n}': 'ஈமோஜி {n}-இன் பெயர்',
  'Tirar {nome}': '{nome}-ஐ நீக்கு',
  'Criar pacote com 1 emoji': '1 ஈமோஜியுடன் தொகுப்பை உருவாக்கு',
  'Criar pacote com {n} emojis': '{n} ஈமோஜிகளுடன் தொகுப்பை உருவாக்கு',
  'Emojis de {comunidade}': '{comunidade}-இன் ஈமோஜிகள்',
  'Junta todos os emojis que {comunidade} tem hoje num pacote só, para as suas outras comunidades (ou as dos seus amigos) instalarem de uma vez.': '{comunidade}-இல் இன்று உள்ள எல்லா ஈமோஜிகளையும் ஒரே தொகுப்பில் சேர்க்கிறது, உங்கள் மற்ற சமூகங்கள் (அல்லது உங்கள் நண்பர்களுடையவை) ஒரே முறையில் நிறுவ.',
