  'Nenhum emoji com "{busca}".': '"{busca}" உள்ள ஈமோஜி இல்லை.',
  'Usados recentemente': 'சமீபத்தில் பயன்படுத்தியவை',
  'Passe o mouse sobre um emoji': 'ஒரு ஈமோஜி மீது சுட்டியை வை',
  'Uma comunidade é um lugar com canais de texto e salas de voz, como um servidor do Discord. Entre na de um amigo com o código de convite dele, ou crie a sua.': 'சமூகம் என்பது உரை அலைவரிசைகளும் குரல் அறைகளும் உள்ள இடம், Discord சர்வர் போல. நண்பரின் அழைப்புக் குறியீட்டைக் கொண்டு அவருடைய சமூகத்தில் சேருங்கள், அல்லது உங்களுடையதை உருவாக்குங்கள்.',
  'Ligue a sua conta do Google, Discord, GitHub ou Steam para entrar no Syden por lá, sem digitar senha. Dá para ligar mais de um, e todos levam a esta mesma conta.': 'கடவுச்சொல் தட்டச்சு செய்யாமல் அங்கிருந்தே Syden-இல் உள்நுழைய உங்கள் Google, Discord, GitHub அல்லது Steam கணக்கை இணையுங்கள். ஒன்றுக்கு மேல் இணைக்கலாம், எல்லாமே இதே கணக்குக்குக் கொண்டுவரும்.',
