  'Criar pacote com {n} sons': '{n} ஒலிகளுடன் தொகுப்பை உருவாக்கு',
  'Instale os pacotes que quiser: os sons deles entram no seu soundboard, e só no seu. As estrelas ajudam a turma a achar os melhores.': 'வேண்டிய தொகுப்புகளை நிறுவுங்கள்: அவற்றின் ஒலிகள் உங்கள் ஒலிப் பலகையில் சேரும், உங்களுடையதில் மட்டும். நட்சத்திரங்கள் குழுவினர் சிறந்தவற்றைக் கண்டுபிடிக்க உதவும்.',
