  'MP3, OGG ou WAV, até {segundos} segundos e 1 MB.': 'MP3, OGG அல்லது WAV, {segundos} வினாடி, 1 MB வரை.',
  'Ícone de {som}': '{som}-இன் படவுரு',
  'Novo nome para {som}': '{som}-க்குப் புதிய பெயர்',
  'Você entrou em {nome}.': '{nome}-இல் சேர்ந்தீர்கள்.',
  'vocês já conversam · mesma comunidade': 'ஏற்கெனவே பேசுகிறீர்கள் · ஒரே சமூகம்',
  'vocês já conversam': 'ஏற்கெனவே பேசுகிறீர்கள்',
  '1 comunidade em comum': '1 பொதுச் சமூகம்',
  '{n} comunidades em comum': '{n} பொதுச் சமூகங்கள்',
  'Não deu certo. Tente de novo.': 'முடியவில்லை. மீண்டும் முயலுங்கள்.',
  'Pedido enviado para {nome}.': '{nome}-க்குக் கோரிக்கை அனுப்பப்பட்டது.',
  'Desfazer amizade com {nome}': '{nome}-உடனான நட்பை முறி',
  'Desfazer amizade': 'நட்பை முறி',
  'mostra quem divide comunidade com você.': 'உங்களுடன் சமூகத்தைப் பகிர்பவர்களைக் காட்டுகிறது.',
  'Recusar o pedido de {nome}': '{nome}-இன் கோரிக்கையை நிராகரி',
  'Nenhum pedido esperando.': 'காத்திருக்கும் கோரிக்கைகள் இல்லை.',
  'esperando resposta': 'பதிலுக்குக் காத்திருக்கிறது',
  'Cancelar o pedido para {nome}': '{nome}-க்கு அனுப்பிய கோரிக்கையை ரத்துசெய்',
  'Precisa ser o nome exato — o Syden não lista contas por pedaços de nome, para ninguém conseguir descobrir quem existe aqui dentro.': 'பெயர் சரியாக அதுவாகவே இருக்க வேண்டும் — இங்கே யார் இருக்கிறார்கள் என்று யாரும் கண்டுபிடிக்காமல் இருக்க, Syden பெயரின் துண்டுகளைக் கொண்டு கணக்குகளைப் பட்டியலிடாது.',
  'Carregar mensagens anteriores': 'முந்தைய செய்திகளை ஏற்று',
  'Arquivo': 'கோப்பு',
