  'A partida ainda não começou.': 'ஆட்டம் இன்னும் தொடங்கவில்லை.',
  'A partida já começou.': 'ஆட்டம் ஏற்கெனவே தொடங்கிவிட்டது.',
  'Só quem começou dá a largada.': 'அழைத்தவர் மட்டுமே ஆட்டத்தைத் தொடங்க முடியும்.',
  'Ainda falta gente para começar.': 'தொடங்க இன்னும் ஆட்கள் போதவில்லை.',
  'Você está assistindo. Dá para entrar na próxima partida.': 'நீ பார்த்துக்கொண்டிருக்கிறாய். அடுத்த ஆட்டத்தில் சேரலாம்.',
  '{nome} quer jogar {jogo}.': '{nome} {jogo} விளையாட விரும்புகிறார்.',
  '{nome} chamou a sala para jogar {jogo}.': '{nome} அறையில் உள்ளவர்களை {jogo} விளையாட அழைத்திருக்கிறார்.',
