  'Polinésia': 'பாலினேசியா',
  'Era: {nome}': 'விடை: {nome}',
  'Escreva o começo do nome e escolha da lista.': 'பெயரின் தொடக்கத்தை எழுதி, பட்டியலிலிருந்து தேர்ந்தெடுங்கள்.',
  'Seu chute': 'உங்கள் ஊகம்',
  'Chutes: {n}': 'ஊகங்கள்: {n}',
  'Monstros de fantasia': 'கற்பனை அரக்கர்கள்',
  'Sai um monstro secreto, e cada um chuta outros da lista. Cada chute mostra o que bate com o secreto: tipo, tamanho, nível, alinhamento e como ele se desloca. Quem acertar com menos chutes ganha mais pontos.': 'ஒரு ரகசிய அரக்கர் தேர்வாகும்; ஒவ்வொருவரும் பட்டியலிலிருந்து மற்றவற்றை ஊகிக்கலாம். ஒவ்வொரு ஊகமும் ரகசியத்துடன் எது பொருந்துகிறது என்று காட்டும்: வகை, அளவு, நிலை, சார்பு, நகரும் விதம். குறைந்த ஊகங்களில் சரியாகக் கண்டுபிடிப்பவருக்கு அதிகப் புள்ளிகள்.',
  'Sai uma figura secreta da mitologia, e cada um chuta outras. Cada chute mostra o que bate com a secreta: a mitologia, o tipo, a forma e o que ela governa. Quem acertar com menos chutes ganha mais pontos.': 'புராணத்திலிருந்து ஒரு ரகசிய உருவம் தேர்வாகும்; ஒவ்வொருவரும் மற்றவற்றை ஊகிக்கலாம். ஒவ்வொரு ஊகமும் ரகசியத்துடன் எது பொருந்துகிறது என்று காட்டும்: புராணம், வகை, வடிவம், அது ஆளும் புலம். குறைந்த ஊகங்களில் சரியாகக் கண்டுபிடிப்பவருக்கு அதிகப் புள்ளிகள்.',
  'Países': 'நாடுகள்',
  'Sai um país secreto, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a sub-região e a população. Quem acertar com menos chutes ganha mais pontos.': 'ஒரு ரகசிய நாடு தேர்வாகும்; ஒவ்வொருவரும் மற்ற நாடுகளை ஊகிக்கலாம். ஒவ்வொரு ஊகமும் ரகசிய நாட்டுக்கான தூரம், திசை, பகுதி, துணைப் பகுதி, மக்கள்தொகை ஆகியவற்றைக் காட்டும். குறைந்த ஊகங்களில் சரியாகக் கண்டுபிடிப்பவருக்கு அதிகப் புள்ளிகள்.',
  'Apagar conversa': 'உரையாடலை நீக்கு',
  'A conversa sai da sua lista e as mensagens somem só para você. As outras pessoas continuam vendo tudo, e uma mensagem nova traz a conversa de volta.': 'உரையாடல் உன் பட்டியலிலிருந்து போய்விடும், செய்திகள் உனக்கு மட்டும் மறைந்துவிடும். மற்றவர்கள் எல்லாவற்றையும் தொடர்ந்து பார்ப்பார்கள், புதிய செய்தி வந்தால் உரையாடல் திரும்ப வரும்.',
  'Responder': 'பதில் அளி',
