  'Pedido de amizade enviado': 'நட்புக் கோரிக்கை அனுப்பப்பட்டது',
  'Iniciar chamada': 'அழைப்பைத் தொடங்கு',
  'Iniciar chamada de vídeo': 'வீடியோ அழைப்பைத் தொடங்கு',
  'Entrar na chamada': 'அழைப்பில் சேர்',
