  'Placar': 'மதிப்பெண்கள்',
  'A chamada terminou.': 'அழைப்பு முடிந்தது.',
  'Não foi possível entrar nesta chamada.': 'இந்த அழைப்பில் சேர முடியவில்லை.',
  'Corrida dos coelhos': 'முயல் பந்தயம்',
  'Horta': 'காய்கறித் தோட்டம்',
  'Setas para dirigir, Espaço para derrapar e carregar o turbo.': 'திருப்ப அம்புக்குறி விசைகள், சறுக்கவும் டர்போவை நிரப்பவும் ஸ்பேஸ்.',
  'Seu recorde: {tempo}': 'உன் சாதனை: {tempo}',
  'Correr contra': 'யாருடன் போட்டி',
  'Nenhum amigo correu nesta pista ainda.': 'இந்தப் பாதையில் இன்னும் எந்த நண்பரும் ஓடவில்லை.',
  'Novo recorde!': 'புதிய சாதனை!',
  'Virar para a esquerda': 'இடப்பக்கம் திருப்பு',
  'Virar para a direita': 'வலப்பக்கம் திருப்பு',
  'Derrapar': 'சறுக்கு',
  'Uma corrida de kart. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, com itens e a Copa da Cenoura.': 'கார்ட் பந்தயம். தனியாக, கடிகாரத்துக்கும் நண்பர்களின் பேய்களுக்கும் எதிராக; குழுவுடன், நேரலையில், பொருட்களுடனும் கேரட் கோப்பையுடனும்.',
  'Pomar': 'பழத்தோட்டம்',
  'Copa da Cenoura': 'கேரட் கோப்பை',
  'contra {nomes}': 'எதிராக: {nomes}',
  'Usar o item': 'பொருளைப் பயன்படுத்து',
  'Olhar para trás': 'பின்னால் பார்',
  'Setas para dirigir, Espaço para derrapar, E para usar o item.': 'திருப்ப அம்புக்குறி விசைகள், சறுக்க ஸ்பேஸ், பொருளைப் பயன்படுத்த E.',
  'Copa da turma': 'குழுவின் கோப்பை',
  'Copas da Cenoura que a turma correu até o fim, na Corrida dos coelhos.': 'முயல் பந்தயத்தில் குழு இறுதிவரை ஓட்டிய கேரட் கோப்பைகள்.',
  'Bosque': 'காடு',
  'Cânion': 'பள்ளத்தாக்கு',
  'Copa do Repolho': 'முட்டைக்கோஸ் கோப்பை',
  'Festa dos coelhos': 'முயல் கொண்டாட்டம்',
  'Cinco rodadas de jogos rápidos, cada um na própria tela: reflexo, pontaria, memória e olho. Quem for melhor em cada rodada ganha mais pontos.': 'வேகமான விளையாட்டுகளின் ஐந்து சுற்றுகள், ஒவ்வொருவரும் தம் திரையில்: அனிச்சை, குறி, நினைவு, கண். ஒவ்வொரு சுற்றிலும் சிறந்தவருக்கு அதிக புள்ளிகள்.',
  'Saque rápido': 'விரைவுச் சுடுதல்',
  'Espere o sinal e aperte o mais rápido que puder. Antes do sinal, está fora.': 'சமிக்ஞைக்குக் காத்திருந்து முடிந்தவரை வேகமாக அழுத்து. சமிக்ஞைக்கு முன் அழுத்தினால் வெளியே.',
  'Medidor de força': 'வலிமை அளவி',
  'Pare a barra o mais perto possível de 100%.': 'பட்டையை 100%க்கு முடிந்தவரை அருகில் நிறுத்து.',
  'Parar o relógio': 'கடிகாரத்தை நிறுத்து',
  'Pare o relógio em 10 segundos exatos. Os números somem depois de 3.': 'கடிகாரத்தைச் சரியாக 10 விநாடிகளில் நிறுத்து. 3க்குப் பிறகு எண்கள் மறையும்.',
  'Jogo dos copos': 'கோப்பை விளையாட்டு',
  'Veja onde fica a cenoura e siga o copo. Acertar mais rápido vale mais.': 'கேரட் எங்கே இருக்கிறது என்று பார்த்து, கோப்பையைப் பின்தொடர். வேகமாகச் சரியாகச் சொன்னால் அதிக மதிப்பு.',
  'Siga o coelho': 'முயலைப் பின்தொடர்',
  'Repita as setas na ordem. A cada acerto, vem mais uma.': 'அம்புகளை வரிசைப்படி திரும்பச் செய். ஒவ்வொரு சரிக்கும் இன்னொன்று சேரும்.',
  'Tiro ao alvo': 'இலக்குச் சுடுதல்',
  'Acerte os alvos que aparecerem. Cada um vale um ponto.': 'தோன்றும் இலக்குகளை அடி. ஒவ்வொன்றுக்கும் ஒரு புள்ளி.',
  'Cedo demais!': 'மிக முன்னதாக!',
  'Não valeu': 'கணக்கில் இல்லை',
  'Sem resposta': 'பதில் இல்லை',
  'Errou': 'தவறு',
  'Nenhum troféu ainda. Fique no pódio de um jogo na sala, com a turma.': 'இன்னும் கோப்பை இல்லை. அறையில் குழுவுடன் ஒரு விளையாட்டில் மேடையில் இடம் பிடி.',
  'Briga na horta': 'தோட்டத்தில் சண்டை',
  'Horta em cascata': 'தோட்ட அருவி',
