  'Galhos': 'கிளைகள்',
  'Copa do Pulo': 'தாவல் கோப்பை',
  'Minigolfe da toca': 'வளையில் மினிகோல்ஃப்',
  '19 de setembro': 'செப்டம்பர் 19',
  '1º de janeiro': 'ஜனவரி 1',
  '25 de dezembro': 'டிசம்பர் 25',
  'A cama': 'கட்டில்',
  'A chuva': 'மழை',
  'A estante': 'புத்தக அலமாரி',
  'A flecha sobe reta e fura o que encontrar. Os balões pequenos valem mais.': 'அம்பு நேராக மேலே பாய்ந்து, எதிர்ப்படுவதையெல்லாம் துளைக்கும். சிறிய பலூன்களுக்கு அதிக மதிப்பு.',
  'A janela': 'ஜன்னல்',
  'A mesa': 'மேசை',
  'A planta': 'செடி',
  'À sala de voz': 'குரல் சேனலுக்கு',
  'A subida está andando.': 'இந்த ஏற்றம் நடந்துகொண்டிருக்கிறது.',
  'A subida não está andando.': 'இந்த ஏற்றம் நடக்கவில்லை.',
  'A tábua racha quando alguém para em cima. Continue andando e empurre os outros para a água!': 'யாராவது மேலே நின்றால் பலகை விரிசல் விடும். நடந்துகொண்டே இரு, மற்றவர்களைத் தண்ணீரில் தள்ளு!',
  'A torre do celeiro': 'களஞ்சியக் கோபுரம்',
  'A toupeira-rei caiu!': 'மூஞ்சூறு அரசன் வீழ்ந்தான்!',
  'A turma caiu.': 'முழுக் குழுவும் வீழ்ந்தது.',
  'A turma inteira contra a toupeira-rei, que sai das tocas em três fases. Fuja das marcas no chão, pegue os torrões azulados e atire de volta. Ganha a turma, ou ninguém.': 'மூன்று கட்டங்களில் வளைகளிலிருந்து வெளிவரும் மூஞ்சூறு அரசனுக்கு எதிராக முழுக் குழுவும். தரையில் உள்ள குறிகளைத் தவிர், நீல நிற மண்கட்டிகளை எடுத்துத் திருப்பி எறி. வெல்வது முழுக் குழு, அல்லது யாருமில்லை.',
  'Abóboras ladeira abaixo': 'சரிவில் உருளும் பூசணிகள்',
  'Acerte os corvos que passarem. No coelhinho, não!': 'கடந்து பறக்கும் காகங்களைச் சுடு. குட்டி முயலை வேண்டாம்!',
  'Acertos: {n}': 'பட்டவை: {n}',
  'Afofa a terra': 'மண்ணைத் தளர்த்தும்',
  'Água e sol': 'தண்ணீரும் வெயிலும்',
  'Alterne ← e → no ritmo. Com pressa demais, o fôlego acaba.': 'தாளத்தில் ← மற்றும் → மாறி மாறி அழுத்து. அவசரப்பட்டால் மூச்சு வாங்கும்.',
  'Ao calendário': 'நாள்காட்டிக்கு',
  'Ao guarda-roupa': 'உடை அலமாரிக்கு',
  'Aperte a seta que aparecer para puxar a corda. Errar trava!': 'தோன்றும் அம்புக்குறியை அழுத்தி கயிற்றை இழு. தவறினால் சிக்கிக்கொள்ளும்!',
  'Aperte para a roda frear. Ela sempre desliza um pouco antes de parar.': 'சக்கரம் நிற்க அழுத்து. நிற்கும் முன் அது எப்போதும் கொஞ்சம் வழுக்கும்.',
  'Aperte sem parar para nadar. Quando vier um tronco, mergulhe!': 'நீந்த விடாமல் அழுத்து. மரக்கட்டை வந்தால் மூழ்கு!',
  'Armadura': 'கவசம்',
  'Arremesso do nabo': 'டர்னிப் எறிதல்',
  'Arrumar como quiser': 'விருப்பம்போல் அடுக்குவது',
  'Arrume a despensa': 'சரக்கறையை ஒழுங்குபடுத்து',
  'As chaves da porteira': 'வாயில் சாவிகள்',
  'As fotos': 'புகைப்படங்கள்',
  'As minhocas': 'மண்புழுக்கள்',
  'Atirar o torrão': 'மண்கட்டியை எறி',
  'Baile da toca': 'வளையில் நடனம்',
  'Balsa a dois': 'இருவர் தெப்பம்',
  'Barraca de tiro': 'சுடும் கடை',
  'Bata nas lagartas que saírem das tocas. No coelhinho, não!': 'வளைகளிலிருந்து வரும் கம்பளிப்பூச்சிகளை அடி. குட்டி முயலை வேண்டாம்!',
  'Bata quando aparecer a flor igual à do quadrinho. Na figura errada, está fora.': 'சட்டத்தில் உள்ள அதே பூ தோன்றும்போது அடி. தவறான படத்தில் அடித்தால் வெளியே.',
  'Batata': 'உருளைக்கிழங்கு',
