  'Você não está nesta subida.': 'நீ இந்த ஏற்றத்தில் இல்லை.',
  'Estoura-balão': 'பலூன் உடை',
  'Coelhos a jato': 'ஜெட் முயல்கள்',
  'A corrida está andando.': 'பந்தயம் நடந்துகொண்டிருக்கிறது.',
  'Cidade à noite': 'இரவு நகரம்',
  'Órbita': 'சுற்றுப்பாதை',
  'Mar de nuvens': 'மேகக் கடல்',
  'Quantos adversários do computador?': 'கணினியின் எதிராளிகள் எத்தனை?',
  'Balões': 'பலூன்கள்',
  'Pegue as caixas e estoure os balões dos outros. Quem fica sem balão sai.': 'பெட்டிகளை எடுத்து மற்றவர்களின் பலூன்களை உடை. பலூன் தீர்ந்தவர் வெளியே.',
  'Você venceu!': 'வெற்றி!',
  '{posicao}º lugar, entre {total}': '{total} பேரில் {posicao}வது இடம்',
  'Balões que sobraram: {n}': 'மீதமுள்ள பலூன்கள்: {n}',
  'Balões estourados: {n}': 'உடைத்த பலூன்கள்: {n}',
  'Freio de ar': 'காற்றுத் தடை',
  'Turbo': 'டர்போ',
  'Pilotar': 'ஓட்டுதல்',
  'Turbo (da segunda volta em diante)': 'டர்போ (இரண்டாவது சுற்றிலிருந்து)',
  '{n} voltas': 'சுற்றுகள்: {n}',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'ஆற்றலே உயிரும் டர்போவும்: ஓரத்தில் மோதினால் அது செலவாகும், இளஞ்சிவப்புப் பட்டை மீண்டும் நிரப்பும்.',
  'A nave explodiu: a energia acabou.': 'கலம் வெடித்தது: ஆற்றல் தீர்ந்தது.',
  'Posição: {posicao} de {total}': 'நிலை: {total} இல் {posicao}',
  'Escolher a pista': 'பாதையைத் தேர்ந்தெடு',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'தொங்கும் பாதையில் கேரட் கலங்களின் பந்தயம், கார்ட்டை விட மிக வேகமானது. ஆற்றலே உயிரும் டர்போவும்: ஓரத்தில் மோதினால் அது செலவாகும், இளஞ்சிவப்புப் பட்டை மீண்டும் நிரப்பும், பாதையை விட்டு வெளியேறுவது விழுவதாகும். தனியாக, கடிகாரத்துக்கும் நண்பர்களின் பேய்களுக்கும் எதிராக.',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'மூடிய அரங்கில் கார்ட்கள், ஒவ்வொன்றிலும் மூன்று பலூன்கள். பெட்டிகளை எடுத்து, பொருட்களால் மற்றவர்களின் பலூன்களை உடை: பலூன் தீர்ந்தவர் வெளியே, கடைசி வரை நிலைப்பவருக்கே வெற்றி.',
  'Esquadrilha da toca': 'வளையின் விமானப் படை',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'கேரட் குட்டி விமானங்கள் தோட்டப் பூச்சிகளுக்கு எதிராக: விதைகளைத் தவிர்க்கவும், உதவிகளை எடுக்கவும், இறுதியில் இயந்திர சோளக்காட்டு பொம்மையை வீழ்த்தவும். குழு அதே அலைகளில் பறக்கிறது, படையின் புள்ளிகள் கூட்டப்படுகின்றன.',
  'O espantalho caiu!': 'சோளக்காட்டு பொம்மை வீழ்ந்தது!',
  'A praga venceu desta vez.': 'இந்த முறை பூச்சிகள் வென்றன.',
  'Placar da esquadrilha: {n}': 'படையின் மதிப்பெண்: {n}',
  'Esquadrilha: {n}': 'படை: {n}',
