  'Bombas: {n}': 'குண்டுகள்: {n}',
  'Bomba': 'குண்டு',
  'Voar': 'பற',
  'Desvie das sementes e derrube a praga. O espantalho vem no fim.': 'விதைகளைத் தவிர்த்து பூச்சிகளை வீழ்த்தவும். சோளக்காட்டு பொம்மை இறுதியில் வரும்.',
  'Sem vidas: agora é torcer pela esquadrilha.': 'உயிர்கள் இல்லை: இப்போது படையை உற்சாகப்படுத்தவும்.',
  'Assistindo: {nome}': 'பார்க்கிறார்: {nome}',
  'A população está no máximo: construa uma Casa.': 'மக்கள்தொகை உச்சத்தில் உள்ளது: ஒரு வீடு கட்டு.',
  'A fila está cheia.': 'வரிசை நிரம்பியது.',
  'Falta: {lista}': 'குறைவு: {lista}',
  'Falta casa': 'வீடு தேவை',
  'Botão direito no mapa: para onde vai quem nasce aqui.': 'வரைபடத்தில் வலது கிளிக்: இங்கே பிறப்பவர்கள் செல்லும் இடம்.',
