  'Resgatar por {valor}': '{valor} க்கு மீட்டெடு',
  'Quem passa por aqui recebe {valor}.': 'இதைக் கடப்பவர் {valor} பெறுவார்.',
  'Quem para aqui paga {valor}.': 'இங்கே நிற்பவர் {valor} செலுத்துவார்.',
  'Quem para aqui perde a próxima vez.': 'இங்கே நிற்பவர் அடுத்த முறையை இழப்பார்.',
  'Quem para aqui tira uma notícia.': 'இங்கே நிற்பவர் ஒரு செய்திச் சீட்டை எடுப்பார்.',
