  'Toque numa cidade sua para construir ou hipotecar.': 'கட்ட அல்லது அடமானம் வைக்க உன் நகரங்களில் ஒன்றைத் தொடு.',
  'Terminar a vez': 'முறையை முடி',
  'Propor troca': 'பரிமாற்றத்தை முன்மொழி',
  '{nome} está fazendo negócios.': '{nome} பேரம் பேசுகிறார்.',
  '{nome} propõe uma troca a {outro}.': '{nome} {outro} க்கு ஒரு பரிமாற்றத்தை முன்மொழிகிறார்.',
  'Recusar': 'மறு',
  'Desistir da troca': 'பரிமாற்றத்தைக் கைவிடு',
  'O que aconteceu': 'என்ன நடந்தது',
  'Até quando?': 'எதுவரை?',
  'rodadas': 'சுற்றுகள்',
  'Até sobrar um': 'ஒருவர் மிஞ்சும் வரை',
  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'பிரேசிலின் தலைநகரங்கள் வழியே சுற்றி, நகரங்களை வாங்கி, அவற்றில் நிற்பவர்களிடம் வாடகை வசூலி. முழுப் பகுதியும் உன்னிடம் இருந்தால் கட்டடங்கள் கட்டலாம். பரிமாறிக்கொள், ஏலங்களில் போட்டியிடு, பணம் தீர்ந்துவிடாமல் பார்த்துக்கொள்.',
  'Trocar a foto': 'படத்தை மாற்று',
  'Pôr uma foto': 'படம் சேர்',
  'Tirar a foto': 'படத்தை நீக்கு',
  'A foto só aparece depois de salvar o recado.': 'செய்தியைச் சேமித்த பிறகுதான் படம் தெரியும்.',
  'Figurinhas': 'ஸ்டிக்கர்கள்',
  'Figurinha não encontrada.': 'ஸ்டிக்கர் கிடைக்கவில்லை.',
  'A sua coleção de figurinhas está cheia. Tire alguma para pôr outra.': 'உன் ஸ்டிக்கர் தொகுப்பு நிரம்பிவிட்டது. புதியதைச் சேர்க்க ஒன்றை நீக்கு.',
  'Figurinha': 'ஸ்டிக்கர்',
  'Salva nas suas figurinhas': 'உன் ஸ்டிக்கர்களில் சேமிக்கப்பட்டது',
  'Não deu para salvar': 'சேமிக்க முடியவில்லை',
  'Salvar figurinha': 'ஸ்டிக்கரைச் சேமி',
  'Essa imagem é grande demais para virar figurinha (até 1 MB).': 'இந்தப் படம் ஸ்டிக்கராக மாற மிகப் பெரியது (1 MB வரை).',
  'Use uma imagem PNG, JPG, GIF ou WEBP.': 'PNG, JPG, GIF அல்லது WEBP படத்தைப் பயன்படுத்து.',
  'Arrumar': 'ஒழுங்குபடுத்து',
  'Criar figurinha': 'ஸ்டிக்கர் உருவாக்கு',
  'Tirar o fundo': 'பின்னணியை நீக்கு',
  'Contorno': 'வெளிக்கோடு',
  'O fundo não é de uma cor só, e ficou como veio.': 'பின்னணி ஒரே நிறத்தில் இல்லை, அதனால் அப்படியே விடப்பட்டது.',
  'No app do Syden, o recorte funciona com qualquer fundo.': 'Syden செயலியில் எந்தப் பின்னணியையும் நீக்கலாம்.',
  'O recorte com o modelo falhou, e ficou o recorte simples.': 'மாதிரியால் நீக்குவது தோல்வியடைந்தது, அதனால் எளிய முறை பயன்படுத்தப்பட்டது.',
  'Mandar figurinha': 'ஸ்டிக்கர் அனுப்பு',
  'Tirar figurinha': 'ஸ்டிக்கரை நீக்கு',
  'Crie figurinhas com as suas imagens, ou salve as que receber numa conversa.': 'உன் படங்களைக் கொண்டு ஸ்டிக்கர்கள் உருவாக்கு, அல்லது உரையாடலில் வந்தவற்றைச் சேமி.',
  'Dominó': 'டோமினோ',
  'Truco': 'ட்ரூக்கோ',
  'Damas': 'டிராஃப்ட்ஸ்',
  'Batalha naval': 'கப்பல் போர்',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'வழக்கமான டோமினோ, 2 முதல் 4 பேர் (4 பேர் என்றால் இணைகளாக). கற்களை முனைகளில் பொருத்து; முதலில் எல்லாவற்றையும் இறக்கியவர் மற்றவர்களின் கைகளில் உள்ள புள்ளிகளைப் பெறுவார்.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'பிரேசிலின் ட்ரூக்கோ, திருப்பிய அட்டையும் துருப்புச் சீட்டுகளும் கொண்டு, 2 பேர் அல்லது 4 பேர் இணைகளாக. ட்ரூக்கோ கேள், ஆறு, ஒன்பது, பன்னிரண்டு என உயர்த்து, அல்லது ஓடு. 12 புள்ளிகள் எடுப்பவர் வெல்வார்.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'பிரேசில் டிராஃப்ட்ஸ்: வெட்டுவது கட்டாயம், முன்னும் பின்னும்; ராணி முழு மூலைவிட்டத்திலும் நகரும். அறை பார்க்கிறது.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'ஒவ்வொருவரும் தன் கப்பல்படையை மறைத்து மற்றவரின் கடலில் சுடுவார்கள். தாக்கினால், மீண்டும் சுடலாம். முழுப் படையையும் முதலில் மூழ்கடிப்பவர் வெல்வார். அறை பார்க்கிறது.',
