  '{nome} correu.': '{nome} ஓடிவிட்டார்.',
  'Mão de onze: jogar valendo 3, ou correr e dar 1 ponto?': 'பதினொன்றின் கை: 3 மதிப்பில் விளையாடவா, அல்லது ஓடி 1 புள்ளி கொடுக்கவா?',
  'Mão de onze: esperando a decisão.': 'பதினொன்றின் கை: முடிவுக்காகக் காத்திருக்கிறது.',
