  // Saúde do servidor: ações da Hetzner e diagnóstico do host
  "Diagnóstico do host": "ஹோஸ்ட் கண்டறிதல்",
  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "கடைசி மூன்று துவக்கங்களிலிருந்து Docker, SSH, logind, கெர்னல் ஆகியவற்றின் வரம்புக்குட்பட்ட பதிவுகள். IP முகவரிகள் இருக்கலாம்.",
  "Atualizar diagnóstico": "கண்டறிதலைப் புதுப்பி",
  "Ainda não há snapshot. Ele será coletado na próxima abertura do cofre.": "இன்னும் ஸ்னாப்ஷாட் இல்லை. பெட்டகம் அடுத்த முறை திறக்கப்படும்போது சேகரிக்கப்படும்.",
  "Coletado em {data}": "{data} அன்று சேகரிக்கப்பட்டது",
  "Medido pela {nome}": "{nome} அளந்தது",
  "Os mesmos números do painel do provedor. Inclui o disco, que o servidor não mede sozinho.": "வழங்குநரின் டாஷ்போர்டில் உள்ள அதே எண்கள். சர்வர் தானாக அளக்காத வட்டும் அடங்கும்.",
  "Ações no servidor": "சர்வரில் செயல்கள்",
  "O histórico da Hetzner: ligar, desligar e reiniciar, pelo painel ou pela API. Uma queda sem ação aqui não foi comandada por esses caminhos.": "Hetzner வரலாறு: டாஷ்போர்டு அல்லது API மூலம் இயக்குதல், நிறுத்துதல், மறுதொடக்கம். இங்கே செயல் இல்லாத தடை இந்த வழிகளில் தூண்டப்படவில்லை.",
  "Nenhuma ação registrada.": "செயல்கள் எதுவும் பதிவாகவில்லை.",
  "Ligar o servidor": "சர்வரை இயக்கு",
