  "Areia": "மணல்",
  "Armadilha": "பொறி",
  "Armadura dos arqueiros": "வில்லாளர்களின் கவசம்",
  "Armadura dos cavaleiros": "குதிரை வீரர்களின் கவசம்",
  "Armadura dos lanceiros": "ஈட்டி வீரர்களின் கவசம்",
  "Arroz": "அரிசி|சாதம்",
  "Artista ou banda": "கலைஞர் அல்லது இசைக்குழு",
  "As pedras andam uma casa na diagonal, para a frente. Comer é obrigatório, também para trás, e vale o lance que come mais.": "காய்கள் மூலைவிட்டமாக முன்னோக்கி ஒரு கட்டம் நகரும். வெட்டுவது கட்டாயம், பின்னோக்கியும்; அதிகம் வெட்டும் நகர்வே செல்லும்.",
  "As regras do xadrez inteiras. Clique na peça e depois na casa: as casas que valem acendem.": "முழு சதுரங்க விதிகள். காயைக் கிளிக் செய்து பின் கட்டத்தைக் கிளிக் செய்யுங்கள்: செல்லும் கட்டங்கள் ஒளிரும்.",
  "Assobio": "சீழ்க்கை",
  "Ataque dos arqueiros": "வில்லாளர்களின் தாக்குதல்",
  "Ataque dos cavaleiros": "குதிரை வீரர்களின் தாக்குதல்",
  "Ataque dos lanceiros": "ஈட்டி வீரர்களின் தாக்குதல்",
  "Até bater": "மோதும் வரை",
  "Atirar a rajada": "சரமாரியாகச் சுடு",
  "Atire no mar do outro: acertou, atira de novo. Vence quem afundar a frota inteira.": "மற்றவரின் கடலில் சுடுங்கள்: பட்டால் மீண்டும் சுடலாம். முழுக் கப்பற்படையையும் மூழ்கடிப்பவர் வெல்வார்.",
  "Atordoar": "மயக்கு",
