  'Com "exatamente 5", seis ou mais seguidas não valem.': "\"சரியாக 5\" என்றால், தொடர்ந்து ஆறு அல்லது அதற்கு மேல் செல்லாது.",
  "Com a troca, quem abre põe três pedras e quem responde escolhe a cor.": "மாற்றத்துடன், தொடங்குபவர் மூன்று காய்களை வைக்கிறார், பதில் தருபவர் நிறத்தைத் தேர்ந்தெடுக்கிறார்.",
  "Com pouca vida, bate mais forte.": "உயிர் குறைவாக இருக்கும்போது அதிக வலுவாக அடிக்கும்.",
