  "Escolha a sua cor.": "உங்கள் நிறத்தைத் தேர்ந்தெடுங்கள்.",
  "Escolha o centro da vila e treine mais um trabalhador.": "கிராம மையத்தைத் தேர்ந்தெடுத்து இன்னொரு தொழிலாளியைப் பயிற்றுவியுங்கள்.",
  "Escolha os papéis e o tempo de cada fase.": "பாத்திரங்களையும் ஒவ்வொரு கட்டத்தின் நேரத்தையும் தேர்ந்தெடுங்கள்.",
  "Escolha quem enfrentar.": "யாரை எதிர்கொள்வது என்று தேர்ந்தெடுங்கள்.",
  "Escolha um trabalhador e clique com o botão direito numa árvore para colher madeira.": "ஒரு தொழிலாளியைத் தேர்ந்தெடுத்து, மரம் வெட்ட ஒரு மரத்தின் மீது வலது கிளிக் செய்யுங்கள்.",
  "Escolha uma casa sua: as sementes andam uma por casa, no sentido anti-horário. Vence quem guardar mais.": "உங்கள் குழி ஒன்றைத் தேர்ந்தெடுங்கள்: விதைகள் கடிகார எதிர்த்திசையில் ஒரு குழிக்கு ஒன்றாகச் செல்லும். அதிகம் சேமிப்பவர் வெல்வார்.",
