  "Estratégia em tempo real, contra o computador ou contra outra pessoa da sala: colete comida, madeira e ouro, construa a vila, avance de era e treine o exército. Ganha quem derrubar o centro da vila do outro, ou construir a Maravilha e mantê-la de pé por 2 minutos.": "நிகழ்நேர உத்தி, கணினிக்கு எதிராக அல்லது அறையில் உள்ள வேறொருவருக்கு எதிராக: உணவு, மரம், தங்கம் சேகரியுங்கள், கிராமத்தைக் கட்டுங்கள், காலத்தில் முன்னேறுங்கள், படையைப் பயிற்றுவியுங்கள். மற்றவரின் கிராம மையத்தை வீழ்த்துபவர், அல்லது அதிசயத்தைக் கட்டி 2 நிமிடங்கள் நிற்க வைப்பவர் வெல்வார்.",
