  "No Oware, a última semente na casa do outro que fica com 2 ou 3 leva essa casa e as anteriores com 2 ou 3. Deixe sempre sementes para o outro.": "Oware-இல், மற்றவரின் குழியில் விழும் கடைசி விதை அதை 2 அல்லது 3 ஆக்கினால், அந்தக் குழியையும் முந்தைய 2 அல்லது 3 உள்ள குழிகளையும் எடுக்கும். மற்றவருக்கு எப்போதும் விதைகளை விட்டுவையுங்கள்.",
