  "A cobra é um animal de que grupo?": "பாம்பு எந்த விலங்குக் குழுவைச் சேர்ந்தது?",
  "A lagarta vira o quê?": "கம்பளிப்பூச்சி எதுவாக மாறும்?",
  "A Lua": "நிலா",
  "A Máscara venceu: a vila tirou {nome} do jogo.": "முகமூடி வென்றது: கிராமம் {nome}-ஐ ஆட்டத்திலிருந்து நீக்கியது.",
