  "Com as armas especiais, cada um tem uma vez o tiro em cruz (a casa e as quatro vizinhas) e uma vez o sonar (quantos navios passam numa área de 3 × 3). As duas gastam a vez.": "சிறப்பு ஆயுதங்களுடன் ஒவ்வொருவருக்கும் ஒரு முறை சிலுவைச் சுடுதல் (கட்டமும் அதன் நான்கு அண்டைக் கட்டங்களும்) மற்றும் ஒரு முறை சோனார் (3 × 3 பகுதியில் எத்தனை கப்பல்கள் செல்கின்றன) உண்டு. இரண்டுமே முறையைச் செலவழிக்கும்.",
  "Com lance voltado, não vale recorde.": "நகர்வைத் திரும்பப் பெற்றால் சாதனை கணக்கில் வராது.",
