  "Em quatro, faça sinais ao parceiro: só ele vê. 😉 zap, 🤨 copas, 😏 espadas, 😛 ouros, 😬 um 3, 😐 nada.": "நான்கு பேர் ஆட்டத்தில் கூட்டாளிக்குச் சைகை காட்டு: கூட்டாளி மட்டுமே பார்க்க முடியும். 😉 ஜாப், 🤨 ஹார்ட்டின், 😏 இஸ்பேடு, 😛 டைமண்ட், 😬 ஒரு 3, 😐 எதுவும் இல்லை.",
