  "Na primeira vez que a vila decidir tirar você do jogo, o amuleto quebra e você fica. Todos passam a ver o seu papel.": "கிராமம் முதல் முறை உன்னை ஆட்டத்திலிருந்து நீக்க முடிவு செய்யும்போது தாயத்து உடையும், நீ ஆட்டத்தில் தொடர்வாய். அதன்பின் எல்லோருக்கும் உன் பாத்திரம் தெரியும்.",
