  "No congelador": "உறைவிப்பானில்",
  "No dominó de pontos, quem deixa as pontas somando 5, 10, 15… marca a soma na hora; a carroça na ponta conta as duas metades. A partida vai a 150.": "புள்ளி டோமினோவில் முனைகளின் கூட்டுத்தொகையை 5, 10, 15… ஆக்குபவர் அந்தத் தொகையை உடனே புள்ளிகளாகப் பெறுவார்; முனையில் உள்ள இரட்டைக் கல்லின் இரு பாதிகளும் கணக்கிடப்படும். ஆட்டம் 150 வரை.",
  "No fim, as setas embaixo do tabuleiro andam pela partida, lance a lance.": "முடிவில், பலகைக்குக் கீழுள்ள அம்புகள் ஆட்டத்தை நகர்வு நகர்வாகக் காட்டும்.",
  "No formigueiro": "எறும்புப் புற்றில்",
  "No forno": "அடுப்பில்",
  "No modo Juntos, a turma resolve o mesmo tabuleiro: cada número aparece para todos, na cor de quem o pôs.": "சேர்ந்து பயன்முறையில் குழு ஒரே பலகையைத் தீர்க்கும்: ஒவ்வொரு எண்ணும் அதை வைத்தவரின் நிறத்தில் எல்லோருக்கும் தெரியும்.",
  "No tabuleiro de 10 × 10, as internacionais, são 20 pedras de cada lado; a regra é a mesma.": "10 × 10 பலகையில், அதாவது சர்வதேச டிராஃப்ட்ஸில், ஒவ்வொரு பக்கமும் 20 காய்கள்; விதி அதேதான்.",
  "Nordeste": "வடகிழக்கு",
  "Norte": "வடக்கு",
  "Nos finais de treino, você joga de brancas e precisa dar o mate. O recorde é em quantos lances.": "பயிற்சி இறுதியாட்டங்களில் நீ வெள்ளைக் காய்களுடன் ஆடி மேட் செய்ய வேண்டும். சாதனை என்பது எத்தனை நகர்வுகளில் என்பதே.",
  "Nova Délhi": "புது தில்லி",
