  "Qual destas é uma fruta cítrica?": "இவற்றில் எது சிட்ரஸ் பழம்?",
  "Qual destas frutas tem um caroço grande?": "இந்தப் பழங்களில் எதற்குப் பெரிய கொட்டை உண்டு?",
