  "Qual destes animais tem o pescoço mais comprido?": "இந்த விலங்குகளில் எதற்கு மிக நீண்ட கழுத்து?",
  "Qual destes animais tem tromba?": "இந்த விலங்குகளில் எதற்குத் தும்பிக்கை உண்டு?",
  "Qual destes animais vive em água doce?": "இந்த விலங்குகளில் எது நன்னீரில் வாழும்?",
  "Qual destes animais vive no polo sul?": "இந்த விலங்குகளில் எது தென் துருவத்தில் வாழும்?",
  "Qual destes é atraído por um ímã?": "இவற்றில் எதைக் காந்தம் ஈர்க்கும்?",
  "Qual destes é o mais leve?": "இவற்றில் எது மிக லேசானது?",
  "Qual destes é o satélite natural da Terra?": "இவற்றில் எது பூமியின் இயற்கைத் துணைக்கோள்?",
