  "Qual é o filhote da ovelha?": "செம்மறியாட்டின் குட்டியை என்னவென்று அழைப்பர்?",
  "Qual é o filhote da vaca?": "பசுவின் குட்டியை என்னவென்று அழைப்பர்?",
  "Qual é o filhote do cavalo?": "குதிரையின் குட்டியை என்னவென்று அழைப்பர்?",
