  "Qual sólido tem seis faces quadradas?": "எந்தத் திண்மத்துக்கு ஆறு சதுர முகங்கள் உண்டு?",
  "Quantas asas tem uma borboleta?": "பட்டாம்பூச்சிக்கு எத்தனை இறக்கைகள்?",
  "Quantas cores tem o arco-íris, na conta mais comum?": "பொதுவான கணக்கில் வானவில்லில் எத்தனை நிறங்கள்?",
  "Quantas horas tem um dia?": "ஒரு நாளில் எத்தனை மணி நேரம்?",
  "Quanto é dez menos três?": "பத்திலிருந்து மூன்றைக் கழித்தால் எவ்வளவு?",
  "Quanto é metade de dez?": "பத்தில் பாதி எவ்வளவு?",
