  "Quanto é três mais quatro?": "மூன்று கூட்டல் நான்கு எவ்வளவு?",
  "Quanto tempo a Terra leva para dar uma volta em torno do Sol?": "பூமி சூரியனை ஒரு முறை சுற்றிவர எவ்வளவு காலம் ஆகும்?",
  "Quanto tempo a Terra leva para girar em torno de si mesma?": "பூமி தன்னைத்தானே ஒரு முறை சுற்ற எவ்வளவு காலம் ஆகும்?",
  "Quantos anos tem um século?": "ஒரு நூற்றாண்டில் எத்தனை ஆண்டுகள்?",
  "Quantos anos tem uma década?": "ஒரு பத்தாண்டில் எத்தனை ஆண்டுகள்?",
  "Quantos braços tem um polvo?": "ஆக்டோபஸுக்கு எத்தனை கைகள்?",
  "Quantos centímetros tem um metro?": "ஒரு மீட்டரில் எத்தனை சென்டிமீட்டர்?",
  "Quantos dentes tem um adulto, normalmente?": "வயது வந்தவருக்கு வழக்கமாக எத்தனை பற்கள்?",
  "Quantos dias tem um ano que não é bissexto?": "லீப் ஆண்டு அல்லாத ஆண்டில் எத்தனை நாட்கள்?",
