  "Rússia": "ரஷ்யா",
  "Saara": "சஹாரா",
  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "ஒரு ரகசிய விலங்கு தேர்வாகும், ஒவ்வொருவரும் ஊகிப்பர். ஒவ்வொரு ஊகமும் ரகசியத்துடன் எது பொருந்துகிறது என்று காட்டும்: வகுப்பு, உணவுமுறை, வாழும் இடம், எடை. குறைந்த ஊகங்களில் கண்டுபிடிப்பவருக்கு அதிகப் புள்ளிகள்.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "ஒரு ரகசிய டைனோசர் தேர்வாகும், ஒவ்வொருவரும் ஊகிப்பர். ஒவ்வொரு ஊகமும் ரகசியத்துடன் எது பொருந்துகிறது என்று காட்டும்: காலம், உணவுமுறை, குழு, நீளம், கண்டெடுக்கப்பட்ட இடம். குறைந்த ஊகங்களில் கண்டுபிடிப்பவருக்கு அதிகப் புள்ளிகள்.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "ஒரு ரகசிய வேதியியல் தனிமம் தேர்வாகும், ஒவ்வொருவரும் ஊகிப்பர். ஒவ்வொரு ஊகமும் ரகசியத்துடன் எது பொருந்துகிறது என்று காட்டும்: குடும்பம், இயற்பியல் நிலை, ஆவர்த்தனம், தொகுதி, அணு எண். குறைந்த ஊகங்களில் கண்டுபிடிப்பவருக்கு அதிகப் புள்ளிகள்.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "பிரேசிலின் ஒரு ரகசிய மாநிலம் தேர்வாகும், ஒவ்வொருவரும் ஊகிப்பர். ஒவ்வொரு ஊகமும் ரகசியம் வரையிலான தூரம், திசை, பகுதி, மக்கள்தொகை, பரப்பளவு, கடற்கரை, வேறு நாட்டுடன் எல்லை ஆகியவற்றைக் காட்டும். குறைந்த ஊகங்களில் கண்டுபிடிப்பவருக்கு அதிகப் புள்ளிகள்.",
