  "Você aguenta o primeiro ataque dos lobisomens. Ninguém fica sabendo.": "ஓநாய்களின் முதல் தாக்குதலை நீ தாங்குவாய். யாருக்கும் தெரியாது.",
  "Você colheu {n} recursos.": "நீ {n} வளங்களைச் சேகரித்தாய்.",
  "Você joga por conta própria: vence se a vila tirar você do jogo no julgamento. Levante suspeitas, mas sem exagero.": "நீ உனக்காகவே ஆடுகிறாய்: விசாரணையில் கிராமம் உன்னை ஆட்டத்திலிருந்து நீக்கினால் நீ வெல்வாய். சந்தேகம் எழுப்பு, ஆனால் அளவுக்கு மீறாமல்.",
